var NAV = [
	["home", "nav_home"],
	["projects", "nav_projects"],
	["sessions", "nav_sessions"],
	["artifact-review", "ar_nav"],
	["delivery", "nav_delivery"],
	["operations", "nav_operations"],
	["cleanup", "nav_cleanup"],
	["settings", "nav_settings"]
];
var workspaceNav = null;
var workspaceIdentity = "";
var workspaceSidebar = null;
function mountWorkspace(name) {
	const identity = state.token ? `${state.epoch}:${state.namespace}` : "";
	if (workspaceIdentity !== identity) {
		workspaceSidebar?.dispose();
		workspaceSidebar = null;
		workspaceNav?.dispose();
		workspaceNav = null;
		workspaceIdentity = identity;
		if (identity) {
			const connection = {
				epoch: state.epoch,
				namespace: state.namespace
			};
			workspaceNav = workspaceNavigation({
				h,
				t,
				api,
				guard: () => assertConnection(connection),
				onEvents,
				namespace: state.namespace,
				errorBox
			});
			document.getElementById("workspace").prepend(workspaceNav.box);
			workspaceSidebar = setupSidebarResizer({
				aside: workspaceNav.box,
				workspace: document.getElementById("workspace"),
				t
			});
		}
	}
	document.body.classList.toggle("has-workspace", Boolean(state.token));
	document.body.classList.toggle("pm-mode", Boolean(state.token) && name === "pm");
	document.getElementById("main").className = ["session", "work"].includes(name) ? "session-view" : name === "pm" ? "pm-view" : "";
	const menu = document.getElementById("workspace-menu");
	menu.hidden = !state.token;
	menu.textContent = t("workspace_navigation");
	menu.onclick = () => {
		const open = document.body.classList.toggle("workspace-nav-open");
		menu.setAttribute("aria-expanded", String(open));
	};
	document.body.classList.remove("workspace-nav-open");
	menu.setAttribute("aria-expanded", "false");
	workspaceNav?.select(location.hash || "#/home");
	const tools = h("details", { class: "workspace-tools" }, h("summary", {}, t("workspace_tools")), h("div", {}, ...NAV.filter(([key]) => ![
		"home",
		"settings",
		"projects"
	].includes(key)).map(([key, label]) => h("a", {
		href: `#/${key}`,
		"aria-current": name === key ? "page" : null
	}, t(label)))));
	document.getElementById("nav").replaceChildren(...state.token ? [
		h("a", {
			href: "#/home",
			class: name === "home" ? "on" : ""
		}, t("nav_home")),
		...pmAvailable(state.caps) ? [h("a", {
			href: "#/pm",
			class: name === "pm" ? "on" : ""
		}, t("pm_nav"))] : [],
		tools
	] : [], h("a", {
		href: "#/settings",
		class: !state.token || name === "settings" ? "on" : ""
	}, t("nav_settings")));
}
var teardown = null;
var generation = 0;
async function route() {
	const mine = ++generation;
	state.viewReady = false;
	if (teardown) {
		teardown();
		teardown = null;
	}
	freshPage();
	let [name, ...rest] = (location.hash.replace(/^#\//, "") || "home").split("/").map(decodeURIComponent);
	if (name === "home" && state.token && state.caps?.managed_installation && !state.caps.hosts?.length) name = "settings";
	mountWorkspace(name);
	const main = document.getElementById("main");
	main.replaceChildren();
	if (!state.token && name !== "settings") {
		const off = await viewSettings(main);
		if (mine !== generation) {
			off?.();
			return;
		}
		teardown = off || null;
		return;
	}
	const off = await ({
		pm: viewPmWorkspace,
		home: viewHome,
		projects: viewProjects,
		project: viewProject,
		item: viewLinkedWorkItem,
		sessions: viewSessions,
		cleanup: viewCleanup,
		approvals: viewApprovals,
		delivery: viewDelivery,
		operations: viewOperations,
		session: viewSession,
		start: viewStart,
		published: viewPublished,
		orchestrate: viewOrchestration,
		op: viewOperation,
		settings: viewSettings,
		"artifact-review": viewArtifactReview,
		work: viewProjectWork,
		dispatch: viewProjectDispatch,
		host: viewHostDiscovery,
		task: viewTask,
		worktree: (main, id) => viewObservedResource(main, "worktree", id)
	}[name] || viewHome)(main, ...rest);
	if (mine !== generation) {
		if (off) off();
		return;
	}
	let preferences, skills;
	if (name === "settings" && state.caps?.features?.host_preferences?.version === 1) {
		const connection = {
			epoch: state.epoch,
			namespace: state.namespace,
			generation
		};
		preferences = modelPreferencesPanel({
			h,
			t,
			api,
			caps: () => state.caps,
			guard: () => assertView(connection),
			submit,
			storageKey: `batc.model-preferences.${connection.namespace}`,
			onEvents,
			errorBox
		});
		main.append(preferences.box);
	}
	if (name === "project" && state.caps?.features?.project_skills?.version === 1) {
		const connection = {
			epoch: state.epoch,
			namespace: state.namespace,
			generation
		};
		skills = projectSkillsPanel({
			h,
			t,
			api,
			caps: () => state.caps,
			guard: () => assertView(connection),
			submit,
			projectId: rest[0],
			storageKey: `batc.project-skills.${connection.namespace}.${rest[0]}`,
			onEvents,
			errorBox
		});
		main.append(skills.box);
	}
	teardown = () => {
		off?.();
		preferences?.dispose();
		skills?.dispose();
	};
	state.viewReady = true;
}
async function start() {
	window.addEventListener("hashchange", route);
	if (nativeDesktop) {
		clearToken();
		const attempt = ++state.nativeAttempt;
		try {
			const status = await nativeStatus();
			if (!status.error && status.credential_available) {
				state.nativeBusy = true;
				route().catch(() => {});
				const caps = await nativeConnect();
				if (attempt === state.nativeAttempt) {
					state.token = "native-credential";
					await activate(caps, status.endpoint);
				}
			}
		} catch (error) {
			if (attempt === state.nativeAttempt) {
				disconnect();
				state.connectionError = error;
				await nativeDisconnect().catch(() => {});
			}
		} finally {
			if (attempt === state.nativeAttempt) state.nativeBusy = false;
		}
	} else {
		const browserSession = await restoreBrowserSession().catch(() => false);
		if (browserSession) clearToken();
		state.token = browserSession ? browserSessionToken : loadToken();
		if (state.token) try {
			await activate(await api("GET", "/capabilities"));
		} catch {
			state.token = null;
		}
	}
	await route();
	streamEvents();
}
start();
